    bh: ["Гидра", "Босс, 4 очка жизни. Каждый раз, теряя очко жизни, она отращивает рядом новую голову (приспешника). Через ход кусает одного из твоих бойцов рядом с собой."],
    bq: ["Пчелиная королева", "Босс, 3 очка жизни. В конце каждого хода своей стороны из улья рядом с ней вылетает пчела (не больше 4). Пчёлы летают на 2 клетки над всем."],
    bk: ["Кракен", "Босс, 4 очка жизни. В конце каждого хода своей стороны его щупальца подтягивают к нему твоего самого ценного бойца на одной линии с ним (до 4 клеток); через ход он пожирает одного из твоих бойцов рядом с собой."],
    bg: ["Ледяная ведьма", "Босс, 3 очка жизни. В конце каждого хода своей стороны она замораживает твоего самого ценного бойца на карте: в следующий ход ты не можешь его активировать."],
    bv: ["Сердце лавы", "Босс, 4 очка жизни. Через ход отмечает красным клетку твоего самого ценного бойца; на следующий ход там бьёт лава: если он всё ещё там, он погибает."],
    bw: ["Ткачиха", "Босс, 3 очка жизни. В конце каждого хода своей стороны она плетёт паутину (клетку, закрытую навсегда) перед твоим ближайшим к ней бойцом (не больше 8 паутин)."],
    bs: ["Призрак", "Босс, 3 очка жизни. В конце каждого хода своей стороны он появляется рядом с твоим самым ценным бойцом. 2 хода из 3 он бесплотен (его нельзя ударить); на 3-й он уносит одного из твоих бойцов рядом с собой, и его можно ударить."],
    bp: ["Феникс", "Босс, 2 очка жизни, но один раз возрождается из пепла с 3 очками жизни, сжигая твоих бойцов рядом с собой. Через ход его пламя убивает 2 твоих бойцов в 2 клетках от него."],
    bb: ["Василиск", "Босс, 4 очка жизни. Через ход он смотрит вдоль прямой линии (отмечена красным); на следующий ход его взгляд превращает в камень первого из твоих бойцов на этой линии."],
    bc: ["Военачальник", "Босс, 4 очка жизни, окружён 5 приспешниками. В конце каждого хода своей стороны его ближайший к тебе приспешник делает шаг к твоим бойцам (и берёт, если достанет)."],
    ab: ["Пчела", "Служанка Королевы: летит на 2 клетки (по прямой или по диагонали) над всем и берёт, приземляясь на врага."],
    ma: ["Гроза", "Бьёт молнией по краю карты на выбор (сверху, снизу, слева или справа) ИЛИ по центру: 2 самых ценных врага там погибают."],
    mb: ["Обменщик", "Меняет местами 2 любых бойцов на карте."],
    mc: ["Кукловод", "Переносит стража противника куда угодно, на пустую клетку."],
    md: ["Командир", "2 твоих бойца делают по шагу (прямо на пустую клетку или взятие по диагонали). Солдаты идут только вперёд."],
    me: ["Вербовщик", "Нанимает сразу 2 бойцов из общего запаса."],
