Object.assign(I18N.DICT.ru.T, {"rq": ["Акула", "Плывёт по прямой (вверх, вниз, влево, вправо) до 3 клеток; берёт, вставая на врага."], "mz": ["Медуза", "Делает 1 шаг по диагонали или, не двигаясь, жалит врага рядом с собой по прямой (вверх, вниз, влево, вправо)."], "pv": ["Осьминог", "Его щупальца хватают врага в 2–3 клетках (в 8 направлениях, через всё) и подтягивают вплотную. Не богов и не боссов."], "sr": ["Сирена", "Её песня отталкивает на клетку всех врагов рядом с ней; вытолкнутые за карту или в дыру погибают."], "bl": ["Левиафан", "Босс, 4 очка жизни. Через ход он ныряет (его нельзя ударить) и отмечает красным клетку твоего самого ценного стража или солдата; на следующий ход всплывает под ним и пожирает его."], "bm": ["Повелитель приливов", "Босс, 4 очка жизни. Через ход прилив отталкивает всех твоих бойцов на клетку к твоей стороне."], "bo": ["Большой коралл", "Босс, 5 очков жизни. В конце каждого хода своей стороны рядом с ним или его кораллом растёт коралл (закрытая клетка) в твою сторону (не больше 6). Каждые 3 хода восстанавливает 1 очко жизни."], "bj": ["Гигантская медуза", "Босс, 3 очка жизни. Через ход молния бьёт твоего ближайшего к ней бойца (не дальше 3 клеток) и перескакивает на соседнего с ним твоего бойца."], "bx": ["Падший бог", "Финальный босс в 2 фазы. Сначала (3 очка жизни) каждый ход призывает приспешника и через ход давит бойца рядом с собой. Затем поднимается снова (4 очка жизни): идёт к тебе и через ход извергает огонь по линии."], "om": ["Мать теней", "Вызывает Тень (солдата теней из общего запаса) на пустую клетку рядом с одним из твоих бойцов."], "of": ["Жнец", "Убивает врага (не бога) рядом с одним из твоих бойцов."], "oe": ["Затмение", "Погружает карту во тьму: в свой следующий ход противник не может ни выставлять, ни активировать бойцов."], "ou": ["Пожиратель душ", "Приносит в жертву одного из твоих бойцов рядом с ним (не бога): ты получаешь 50 маны."], "oa": ["Убийца", "Делает 1 шаг на пустую клетку или прыгает на 2 клетки (по прямой или по диагонали, через всё); берёт, приземляясь на врага."], "ob": ["Туман", "Телепортируется на пустую клетку не дальше 3 клеток или на врага не дальше 2 клеток, чтобы его взять."], "oc": ["Ворон", "Летит по диагонали до 3 клеток через всё; берёт, приземляясь на врага."], "ol": ["Клинок", "Проходит 2 клетки по прямой (вверх, вниз, влево, вправо) и убивает врагов на своём пути."], "ox": ["Летучая мышь", "Летит на 2 клетки (по прямой или по диагонали) через всё; берёт, приземляясь на врага."], "os": ["Тень", "Солдат теней: делает 1 шаг по прямой (даже назад) на пустую клетку; берёт по диагонали вперёд."], "bv": ["Сердце лавы", "Босс, 4 очка жизни. Через ход отмечает красным клетку твоего самого ценного стража или солдата; на следующий ход там бьёт лава: если он всё ещё там, он погибает."]});
