Object.assign(I18N.DICT.ru.T, {"na": ["Одержимость", "Захватывает вражеского солдата или стража рядом с твоим бойцом: он переходит на твою сторону (у противника он считается потерянным)."], "nb": ["Проклятие", "Проклинает врага (не бога) в любом месте карты: если в конце следующего хода его стороны он всё ещё на той же клетке, он погибает."], "nc": ["Проход", "Проводит твоего бойца (не бога) сквозь тени: он выходит на пустую клетку рядом с другим твоим бойцом."], "nd": ["Похититель душ", "Крадёт у противника до 30 маны."], "ne": ["Вой", "Все враги (не боги) на твоей половине карты отступают на клетку к своей стороне, если клетка свободна."], "nf": ["Зов мёртвых", "Приводит в твой резерв 2 Тени (солдат теней) и ещё по 1 за каждого потерянного стража (не больше 4)."], "ng": ["Оковы", "Сковывает вражеского бойца (даже бога): его нельзя активировать в следующие 2 хода его стороны."], "nh": ["Врата теней", "Открывает врата: твой страж или солдат выходит на пустую клетку зоны расстановки противника."], "ni": ["Мор", "Гибнут все вражеские солдаты, стоящие рядом хотя бы с 2 твоими бойцами."], "nj": ["Саван", "Укрывает твоего бойца и твоих бойцов рядом с ним: ничто не может их убить до твоего следующего хода."], "nk": ["Чёрный прилив", "Все твои Тени (солдаты теней) продвигаются на клетку к противнику, если клетка свободна."], "n1": ["Призрак", "Проходит сквозь всё: опускается на пустую клетку не дальше 3 клеток. Там соседние вражеские солдаты умирают от страха, а соседних вражеских стражей нельзя активировать в их следующий ход."], "n2": ["Гуль", "Делает 1 шаг в любом направлении; берёт, вставая на врага. После взятия может шагнуть ещё раз (не больше 3 шагов)."], "n3": ["Вампир", "Делает 1 шаг на пустую клетку (8 направлений) или, не двигаясь, кусает врага в 1–2 клетках по прямой или диагонали, через всё (не бога): враг погибает, а ты получаешь 20 маны."], "n4": ["Паук", "Делает 1 прямой шаг на пустую клетку или набрасывает паутину на 1-го вражеского бойца по прямой не дальше 4 клеток: солдат погибает, страж или бог не может быть активирован 2 хода своей стороны."], "n5": ["Полтергейст", "Делает 1 прямой шаг на пустую клетку или хватает врага в 1–2 клетках по прямой или диагонали (не бога) и швыряет его на 2 клетки дальше: если он падает за карту, в дыру или на бойца, он погибает."], "n6": ["Змей", "Ползёт до 3 прямых шагов (вверх, вниз, влево, вправо), поворачивая как хочет, по пустым клеткам; берёт, вставая на врага."], "n7": ["Оборотень", "Делает 1 шаг в любом направлении (берёт, вставая на врага). Если рядом 2 врага или больше, он может впасть в ярость: все соседние враги погибают (не боги)."], "n8": ["Личинка", "Делает 1 прямой шаг на пустую клетку или берёт по диагонали. Когда она погибает, вокруг неё вылупляются 2 Тени."], "n9": ["Демон", "Делает 1 шаг в любом направлении (берёт, вставая на врага) или возникает на пустой клетке рядом с вражеским богом."], "nl": ["Скелет", "Делает 1 прямой шаг (берёт, вставая на врага) или, не двигаясь, бросает кость во врага в 2–3 клетках по прямой (не в бога). Когда погибает, поднимается Тенью рядом."], "nm": ["Отражение", "Делает 1 прямой шаг на пустую клетку или прыгает в своё отражение — симметричную клетку в том же ряду с другой стороны (слева ↔ справа); там берёт врага, но не бога."], "nn": ["Палач", "Делает 1 шаг на пустую клетку (8 направлений) или, не двигаясь, казнит соседнего врага (не бога), который стоит рядом и с другим твоим бойцом."], "no": ["Ползун", "Ползёт прямо к противнику до 4 клеток по пустым клеткам; берёт, вставая на врага."]});
I18N.DICT.ru.T.oa[1] = "Делает 1 шаг на пустую клетку или прыгает на 2–3 клетки (по прямой или диагонали, через всё); берёт, вставая на врага.";
I18N.DICT.ru.T.oc[1] = "Летит по диагонали до 4 клеток через всё; берёт, приземляясь на врага.";
// armée des Ombres : descriptions courtes
I18N.DICT.ru.T.na[1] = "Крадёт врага (не бога) рядом с твоим бойцом: он переходит к тебе.";
I18N.DICT.ru.T.nb[1] = "Проклинает врага: если он не сдвинется в свой ход, он погибнет.";
I18N.DICT.ru.T.nc[1] = "Телепортирует твоего бойца к другому твоему бойцу.";
I18N.DICT.ru.T.nd[1] = "Крадёт у противника 40 маны.";
I18N.DICT.ru.T.ne[1] = "Отталкивает на клетку всех врагов на твоей половине карты.";
I18N.DICT.ru.T.nf[1] = "+3 Тени (солдаты) в резерв, +1 за каждого потерянного стража.";
I18N.DICT.ru.T.ng[1] = "Враг (даже бог) не может действовать 2 хода.";
I18N.DICT.ru.T.nh[1] = "Телепортирует твоего стража или солдата в зону противника.";
I18N.DICT.ru.T.ni[1] = "Убивает всех вражеских солдат рядом с твоими бойцами.";
I18N.DICT.ru.T.nj[1] = "Твой боец и его соседи не могут погибнуть до твоего хода.";
I18N.DICT.ru.T.nk[1] = "Все твои Тени (солдаты) продвигаются на клетку.";
I18N.DICT.ru.T.om[1] = "Порождает Тень (солдата) рядом с твоим бойцом.";
I18N.DICT.ru.T.of[1] = "Убивает врага (не бога) рядом с твоим бойцом.";
I18N.DICT.ru.T.oe[1] = "В следующий ход противника: ни ставить, ни активировать.";
I18N.DICT.ru.T.ou[1] = "Жертвует твоего бойца рядом с собой: +60 маны.";
I18N.DICT.ru.T.oa[1] = "1 шаг или прыжок на 2–3 клетки через всё; берёт при приземлении.";
I18N.DICT.ru.T.ob[1] = "Телепортируется на свободную тёмную клетку не дальше 4 клеток или съедает соседа.";
I18N.DICT.ru.T.oc[1] = "Летит по диагонали до 4 клеток; берёт при приземлении.";
I18N.DICT.ru.T.ol[1] = "Рвётся на 2 клетки вперёд и убивает всё на пути.";
I18N.DICT.ru.T.ox[1] = "Летит на 1–2 клетки через всё; берёт при приземлении.";
I18N.DICT.ru.T.os[1] = "1 прямой шаг (даже назад); берёт по диагонали вперёд.";
I18N.DICT.ru.T.n1[1] = "Опускается не дальше 3 клеток; убивает соседних вражеских солдат, сковывает стражей.";
I18N.DICT.ru.T.n2[1] = "1 шаг (берёт); после каждого взятия шагает ещё раз (не больше 3).";
I18N.DICT.ru.T.n3[1] = "Кусает врага в 2 клетках, не двигаясь (не бога): +20 маны. Или 1 шаг.";
I18N.DICT.ru.T.n4[1] = "Паутина на 4 клетки по прямой: убивает солдата, сковывает стража на 2 хода. Или 1 шаг.";
I18N.DICT.ru.T.n5[1] = "Швыряет ближнего врага на 2 клетки дальше: он гибнет, если неудачно упадёт. Или 1 шаг.";
I18N.DICT.ru.T.n6[1] = "Ползёт до 4 клеток, поворачивая как хочет; берёт в конце.";
I18N.DICT.ru.T.n7[1] = "1 шаг (берёт); рядом с 2 врагами или больше — убивает всех.";
I18N.DICT.ru.T.n8[1] = "1 шаг, берёт по диагонали; погибая, даёт 2 Тени.";
I18N.DICT.ru.T.n9[1] = "1 шаг (берёт) или возникает рядом с вражеским богом.";
I18N.DICT.ru.T.nl[1] = "1 шаг (берёт) или бросает кость на 2–3 клетки; погибнув, возвращается Тенью.";
I18N.DICT.ru.T.nm[1] = "1 шаг или прыжок в своё отражение (тот же ряд, другая сторона) со взятием.";
I18N.DICT.ru.T.nn[1] = "Убивает соседнего врага, который стоит рядом и с другим твоим бойцом. Или 1 шаг.";
I18N.DICT.ru.T.no[1] = "Мчится до 4 клеток к противнику; берёт в конце.";
// armée des Ombres : descriptions claires
I18N.DICT.ru.T.na[1] = "Враг рядом с твоим бойцом переходит на твою сторону (не бог).";
I18N.DICT.ru.T.nb[1] = "Проклинает врага: если к концу своего следующего хода он не сдвинулся, он погибает.";
I18N.DICT.ru.T.nc[1] = "Переносит твоего бойца (не бога) на пустую клетку рядом с другим твоим бойцом.";
I18N.DICT.ru.T.nd[1] = "Забирает у противника 50 маны и отдаёт тебе.";
I18N.DICT.ru.T.ne[1] = "Враги (не боги) на твоей стороне карты отступают на клетку.";
I18N.DICT.ru.T.nf[1] = "Добавляет в резерв 3 Тени (солдата), +1 за каждого потерянного стража.";
I18N.DICT.ru.T.ng[1] = "Выбранного врага (даже бога) нельзя активировать 2 его следующих хода.";
I18N.DICT.ru.T.nh[1] = "Переносит твоего стража или солдата на пустую клетку в зоне противника.";
I18N.DICT.ru.T.ni[1] = "Убивает всех вражеских солдат рядом хотя бы с одним твоим бойцом.";
I18N.DICT.ru.T.nj[1] = "Выбери своего бойца: он и твои бойцы рядом с ним не могут погибнуть до твоего следующего хода.";
I18N.DICT.ru.T.nk[1] = "Каждая твоя Тень (солдат) продвигается на клетку к противнику.";
I18N.DICT.ru.T.om[1] = "Ставит Тень (солдата) на пустую клетку рядом с твоим бойцом.";
I18N.DICT.ru.T.of[1] = "Убивает врага (не бога) рядом с твоим бойцом.";
I18N.DICT.ru.T.oe[1] = "В свой следующий ход противник не может ни ставить, ни активировать бойцов.";
I18N.DICT.ru.T.ou[1] = "Жертвует твоего бойца рядом с ним (не бога): ты получаешь 60 маны.";
I18N.DICT.ru.T.oa[1] = "1 прямой шаг или прыжок по прямой на 2–3 клетки через всё. Берёт врага на клетке приземления.";
I18N.DICT.ru.T.ob[1] = "Телепортируется на пустую тёмную клетку не дальше 4 клеток или берёт соседнего врага.";
I18N.DICT.ru.T.oc[1] = "Летит по диагонали до 4 клеток через всё. Берёт врага на клетке приземления.";
I18N.DICT.ru.T.ol[1] = "Продвигается на 2 клетки в одном из 8 направлений и убивает всех врагов на этих 2 клетках.";
I18N.DICT.ru.T.ox[1] = "1 шаг на пустую клетку или полёт на 2 клетки в 8 направлениях через всё. Берёт врага на клетке приземления.";
I18N.DICT.ru.T.os[1] = "1 прямой шаг на пустую клетку (даже назад). Берёт по диагонали вперёд.";
I18N.DICT.ru.T.n1[1] = "Опускается на пустую клетку не дальше 3 клеток. Там соседние вражеские солдаты погибают, а соседние стражи скованы на 1 ход.";
I18N.DICT.ru.T.n2[1] = "1 шаг в 8 направлениях, берёт врага на клетке. После взятия может шагнуть ещё раз (не больше 3).";
I18N.DICT.ru.T.n3[1] = "Не двигаясь, убивает врага в 1–2 клетках по прямой или диагонали, если между ними ничего нет (не бога): +10 маны. Или 1 шаг на пустую клетку.";
I18N.DICT.ru.T.n4[1] = "Пускает паутину в 1-го врага по прямой не дальше 4 клеток: солдат погибает, страж или бог скован на 2 хода. Или 1 шаг по диагонали (берёт врага).";
I18N.DICT.ru.T.n5[1] = "Швыряет врага в 1–2 клетках (не бога) на 2 клетки дальше: он погибает, если вылетает за карту, падает в дыру или на бойца. Или 1 шаг (берёт врага).";
I18N.DICT.ru.T.n6[1] = "Делает до 3 прямых шагов по пустым клеткам, поворачивая как хочет. Берёт врага только не дальше 2 шагов.";
I18N.DICT.ru.T.n7[1] = "1 шаг в 8 направлениях (берёт врага). Если он берёт или стоит рядом с 2 врагами и больше, он впадает в ярость: все соседние враги погибают (не боги).";
I18N.DICT.ru.T.n8[1] = "1 прямой шаг (берёт врага) или взятие по диагонали. Когда она погибает, вокруг появляются 2 Тени.";
I18N.DICT.ru.T.n9[1] = "1 шаг в 8 направлениях (берёт врага на клетке) или появляется на пустой клетке рядом с вражеским богом.";
I18N.DICT.ru.T.nl[1] = "1 прямой шаг (берёт врага) или, не двигаясь, убивает врага в 2–3 клетках по прямой (не бога). Когда погибает, рядом появляется Тень.";
I18N.DICT.ru.T.nm[1] = "1 шаг в 8 направлениях (берёт врага) или прыжок на зеркальную клетку по другую сторону своего ряда или столбца со взятием врага (не бога).";
I18N.DICT.ru.T.nn[1] = "1 шаг в 8 направлениях (берёт врага). Или, не двигаясь, убивает соседнего врага, который стоит рядом и с другим твоим бойцом (не бога).";
I18N.DICT.ru.T.no[1] = "Продвигается прямо к противнику сколько хочет по пустым клеткам и берёт врага на клетке прибытия. Или 1 шаг на пустую клетку.";
I18N.DICT.ru.T.n3[1] = "Не двигаясь, кусает соседнего врага (не бога): тот погибает, а ты получаешь 10 маны. Или 1 шаг на пустую клетку.";
I18N.DICT.ru.T.n6[1] = "Делает до 3 прямых шагов по пустым клеткам, поворачивая как хочет. Берёт только врага, стоящего вплотную (по прямой).";
I18N.DICT.ru.T.n8[1] = "1 шаг в 8 направлениях (берёт врага). Когда она погибает, вокруг появляются 2 Тени.";
// équilibrage du 2026-10-24
I18N.DICT.ru.T.g3[1] = "Стреляет по диагонали: убивает первого врага на диагонали, не двигаясь. Или делает 1 шаг в любую сторону.";
I18N.DICT.ru.T.g4[1] = "Продвигается на 1 клетку в любом из 8 направлений, толкая весь ряд перед собой (вытолкнутый за карту или в яму погибает), затем может сделать 2-й шаг на пустую клетку или на вражеского солдата, чтобы взять его.";
I18N.DICT.ru.T.g6[1] = "Может сначала сделать 1 шаг, затем бьёт по всем клеткам вокруг: все соседние враги погибают.";
I18N.DICT.ru.T.c5[1] = "Приземляется на любую клетку дальше 6 клеток (строки + столбцы); может взять там солдата или стража дальше 8 клеток, но никогда не бога.";
I18N.DICT.ru.T.c6[1] = "1 шаг в любую сторону (берёт врага). Или превращает соседнего своего солдата в 60 маны (солдат исчезает), и ты сразу ходишь ещё раз. Или даёт тебе 30 маны.";
I18N.DICT.ru.T.lc[1] = "Бьёт 4 клетки перед собой по прямой (вверх, вниз, влево или вправо), не двигаясь. Если в этом направлении нет врагов, делает шаг.";
I18N.DICT.ru.T.n6[1] = "Делает до 4 прямых шагов по пустым клеткам, поворачивая как угодно, и может закончить ход на враге, чтобы взять его.";
I18N.DICT.ru.T.n8[1] = "1 шаг в 8 направлениях (берёт врага). Когда она погибает, вокруг появляются 3 Тени.";
I18N.DICT.ru.T.cv[1] = "Прыгает буквой Г, как шахматный конь, через что угодно. Или делает 1 шаг в любую сторону.";
I18N.DICT.ru.T.n6[1] = "Делает до 4 прямых шагов по пустым клеткам, поворачивая как угодно. Может взять врага не дальше чем в 2 шагах.";
I18N.DICT.ru.T.g4[1] = "Продвигается на 1 клетку в любом из 8 направлений, толкая весь ряд перед собой (вытолкнутый за карту или в яму погибает), затем может сделать 2-й шаг прямо — на пустую клетку или на врага (не бога), чтобы взять его.";
I18N.DICT.ru.T.c2[1] = "Ходит по диагонали на сколько угодно клеток (как шахматный слон). Или делает 1 прямой шаг на пустую клетку.";
I18N.DICT.ru.T.n6[1] = "Делает до 3 прямых шагов по пустым клеткам, поворачивая как угодно. Может взять врага не дальше чем в 2 шагах.";
I18N.DICT.ru.T.c3[1] = "Телепортируется на клетку рядом с солдатом (любым) или с одним из твоих бойцов.";
// boss rééquilibrés (2026-10-24)
I18N.DICT.ru.T.bs[1] = "Босс, 4 очка жизни. В конце каждого хода своей стороны появляется рядом с твоим самым ценным бойцом. Неуязвим (его нельзя ударить) 1 ход из 3; каждые 3 хода уносит одного из твоих бойцов рядом с собой.";
I18N.DICT.ru.T.bg[1] = "Босс, 2 очка жизни. Раз в два хода замораживает твоего самого ценного бойца на карте: в следующий ход его нельзя активировать.";
I18N.DICT.ru.T.bv[1] = "Босс, 2 очка жизни. Раз в два хода отмечает красным клетку твоего самого ценного стража или солдата; на следующий ход там извергается лава: если он ещё там, он погибает.";
I18N.DICT.ru.T.bc[1] = "Босс, 3 очка жизни, окружён 4 приспешниками. В конце каждого хода своей стороны ближайший к тебе приспешник делает шаг к твоим бойцам (и берёт, если доходит).";
I18N.DICT.ru.T.bq[1] = "Босс, 4 очка жизни. В конце каждого хода своей стороны из улья рядом с ней вылетает пчела (не больше 4). Пчёлы летают на 2 клетки поверх всего.";
I18N.DICT.ru.T.sa[1] = "Босс Света, 5 очков жизни. Каждый ход его свет ослепляет всех твоих бойцов в его строке и столбце: в следующий ход их нельзя активировать.";
I18N.DICT.ru.T.sp[1] = "Босс Света, 5 очков жизни. Пока рядом с ним 2 его бойца, они его защищают: твои удары ничего не делают. Сначала убей его стражей! Раз в два хода он идёт к тебе (иногда оставляя стражей позади) и каждые 3 хода бьёт бойца рядом с собой.";
I18N.DICT.ru.T.bp[1] = "Босс, 2 очка жизни, но однажды возрождается из пепла с 2 очками жизни, сжигая твоих бойцов рядом. Раз в два хода его пламя убивает 2 твоих бойцов в 2 клетках от него.";
I18N.DICT.ru.T.bt[1] = "Босс, 5 очков жизни. В конце каждого хода своей стороны продвигается на клетку к твоему ближайшему бойцу; раз в два хода давит одного из твоих бойцов рядом с собой.";
I18N.DICT.ru.T.n6[1] = "Делает до 3 прямых шагов по пустым клеткам, поворачивая как угодно. Берёт только врага вплотную (по прямой).";
// descriptions plus claires (2026-10-30)
I18N.DICT.ru.T.g4[1] = "Делает 1 шаг в любую сторону. Если перед ним бойцы, он толкает их всех на клетку (вытолкнутый за карту или в яму погибает). Затем может сделать 2-й шаг прямо — на пустую клетку или на врага (не бога), чтобы убить его.";
I18N.DICT.ru.T.g5[1] = "Делает до 3 шагов подряд. Каждый шаг — прямо (вверх, вниз, влево, вправо) на пустую клетку или по диагонали на врага, чтобы убить его.";
I18N.DICT.ru.T.g6[1] = "Может сначала сделать 1 шаг, затем крутится на месте: все враги на 8 клетках вокруг него погибают.";
I18N.DICT.ru.T.c3[1] = "Исчезает и появляется на клетке рядом с солдатом (любой стороны) или с одним из твоих бойцов. Если на этой клетке враг, она его убивает.";
I18N.DICT.ru.T.c5[1] = "Прыгает далеко: приземляется на клетку дальше 6 клеток (строки плюс столбцы). Если там вражеский солдат, она его убивает; вражеского стража — только если он дальше 8 клеток; бога — никогда.";
I18N.DICT.ru.T.c8[1] = "Делает 1 шаг в любую сторону (убивает врага, если он там). Или перепрыгивает через целый ряд стоящих вплотную бойцов и приземляется на пустую клетку сразу за ними.";
I18N.DICT.ru.T.n1[1] = "Встаёт на пустую клетку не дальше 3 клеток. При появлении соседние вражеские солдаты погибают, а соседних вражеских стражей нельзя активировать в следующий ход.";
I18N.DICT.ru.T.n4[1] = "Пускает паутину прямо (вверх, вниз, влево, вправо) в первого врага не дальше 4 клеток: солдат погибает; страж или бог застревает и не может быть активирован 2 хода. Или делает 1 шаг по диагонали (убивает врага, если он там).";
I18N.DICT.ru.T.n5[1] = "Хватает врага (не бога) в 1–2 клетках по прямой или диагонали и бросает его на 2 клетки дальше в ту же сторону: он погибает, если вылетает за карту, падает в яму или на другого бойца. Или делает 1 шаг (убивает врага, если он там).";
I18N.DICT.ru.T.nl[1] = "Делает 1 шаг прямо (вверх, вниз, влево, вправо) и убивает врага, если он там. Или, не двигаясь, убивает врага (не бога) в 2–3 клетках по прямой. Когда он погибает, рядом появляется Тень (солдат).";
I18N.DICT.ru.T.nm[1] = "Делает 1 шаг в любую сторону (убивает врага, если он там). Или прыгает на зеркальную клетку на другой стороне карты — в своей строке или столбце (убивает там врага, не бога).";
I18N.DICT.ru.T.ob[1] = "Телепортируется на пустую тёмную клетку не дальше 4 клеток. Или, не двигаясь, убивает врага рядом с собой.";
